const config = $input.first().json;
const candidateProfile = String(config.candidateProfile ?? '').trim();
if (!candidateProfile) {
  throw new Error('Workflow Configuration candidateProfile is required. Paste your resume/profile text before running the workflow.');
}

const maxPages = Math.max(1, Number(config.maxPages ?? 8));
const pageSize = Math.max(1, Number(config.pageSize ?? 25));
const minFitScoreRaw = Number(config.minFitScore ?? 7);
const minFitScore = Number.isFinite(minFitScoreRaw)
  ? Math.min(10, Math.max(1, Math.round(minFitScoreRaw)))
  : 7;
const output = [];

for (let pageIndex = 0; pageIndex < maxPages; pageIndex++) {
  output.push({
    json: {
      ...config,
      candidateProfile,
      minFitScore,
      pageIndex,
      start: pageIndex * pageSize,
      fetchedAt: new Date().toISOString(),
    },
  });
}

return output;

const decodeHtml = (value = '') => value
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&#x27;/gi, "'")
  .replace(/&#x2F;/gi, '/')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .trim();

const cleanText = (value = '') => decodeHtml(value).replace(/\s+/g, ' ').trim();
const stripTags = (value = '') => cleanText(value.replace(/<[^>]+>/g, ' '));
const seenInRun = new Set();
const jobs = [];

for (const item of $input.all()) {
  const html = item.json.html || '';
  const pageIndex = Number(item.json.pageIndex ?? 0);
  const start = Number(item.json.start ?? 0);
  const cards = html.split('<div class="base-card relative').slice(1);

  for (const cardPart of cards) {
    const card = `<div class="base-card relative${cardPart}`;
    const jobId = card.match(/data-entity-urn="urn:li:jobPosting:(\d+)"/)?.[1];
    const jobUrlRaw = card.match(/class="base-card__full-link[\s\S]*?href="([^"]+)"/)?.[1];
    const titleRaw = card.match(/<h3 class="base-search-card__title">([\s\S]*?)<\/h3>/)?.[1];
    const companyRaw = card.match(/<h4 class="base-search-card__subtitle">[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)?.[1];
    const locationRaw = card.match(/<span class="job-search-card__location">([\s\S]*?)<\/span>/)?.[1];
    const postedDate = card.match(/<time class="job-search-card__listdate(?:--new)?[^"]*" datetime="([^"]+)"/)?.[1] ?? null;
    const postedTextRaw = card.match(/<time class="job-search-card__listdate(?:--new)?[^"]*"[^>]*>([\s\S]*?)<\/time>/)?.[1];

    const title = stripTags(titleRaw || '');
    const company = stripTags(companyRaw || '');
    const location = stripTags(locationRaw || '');
    const postedText = stripTags(postedTextRaw || '');
    const jobUrl = decodeHtml(jobUrlRaw || '');
    const canonicalJobUrl = jobUrl ? jobUrl.split('?')[0] : '';
    const dedupeKey = jobId || canonicalJobUrl;

    if (!dedupeKey || !title || !canonicalJobUrl) continue;
    if (seenInRun.has(dedupeKey)) continue;

    seenInRun.add(dedupeKey);
    jobs.push({
      json: {
        jobId,
        title,
        company,
        location,
        postedDate,
        postedText,
        jobUrl: canonicalJobUrl,
        keywords: item.json.keywords,
        locationFilter: item.json.location,
        remoteFilter: true,
        postedWithinSeconds: Number(item.json.postedSeconds),
        pageIndex,
        start,
        fetchedAt: item.json.fetchedAt,
        source: 'LinkedIn Jobs Guest Search'
      }
    });
  }
}

jobs.sort((a, b) => {
  const aTime = a.json.postedDate ? Date.parse(a.json.postedDate) : 0;
  const bTime = b.json.postedDate ? Date.parse(b.json.postedDate) : 0;
  if (aTime !== bTime) return bTime - aTime;
  return a.json.pageIndex - b.json.pageIndex;
});

return jobs;

const jobs = $input.all().map(item => item.json);
return [
  {
    json: {
      jobCount: jobs.length,
      detectedAt: new Date().toISOString(),
      jobs,
      jobsPayload: JSON.stringify(jobs, null, 2),
    },
  },
];

