const rawJobCount = Number($('Prepare Jobs For AI Deduplication').first().json.jobCount || 0);

const parseMaybeJson = (value) => {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;

  try {
    return JSON.parse(trimmed);
  } catch {
    return value;
  }
};

const findJobsArray = (value, depth = 0, seen = new Set()) => {
  if (depth > 8 || value == null) return null;

  const parsed = parseMaybeJson(value);
  if (Array.isArray(parsed)) return parsed;
  if (!parsed || typeof parsed !== 'object') return null;
  if (seen.has(parsed)) return null;

  seen.add(parsed);

  if (Array.isArray(parsed.jobs)) return parsed.jobs;

  for (const key of ['output', 'response', 'data', 'result']) {
    const nested = findJobsArray(parsed[key], depth + 1, seen);
    if (Array.isArray(nested)) return nested;
  }

  return null;
};

const groups = findJobsArray($json) ?? [];
if (rawJobCount > 0 && groups.length === 0) {
  throw new Error('AI Deduplicate Jobs returned no usable jobs array. Check the AI node output and look for a JSON string in output/output.jobs.');
}

const normalizeText = (value = '') => String(value).trim();
const makeKey = (company, title) => `${normalizeText(company).toLowerCase()}|${normalizeText(title).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()}`;

return groups.map((group, index) => {
  const company = normalizeText(group.company || 'Unknown company');
  const title = normalizeText(group.title || 'Unknown role');
  const regions = Array.from(new Set((Array.isArray(group.regions) ? group.regions : [])
    .map(value => normalizeText(value))
    .filter(Boolean)));
  const jobUrls = Array.from(new Set((Array.isArray(group.jobUrls) ? group.jobUrls : [])
    .map(value => String(value).trim())
    .filter(Boolean)));
  const duplicateCount = Number(group.duplicateCount || jobUrls.length || regions.length || 1);

  return {
    json: {
      canonicalKey: normalizeText(group.canonicalKey || makeKey(company, title)),
      company,
      title,
      regions,
      primaryLocation: normalizeText(group.primaryLocation || regions[0] || 'Worldwide'),
      postedDate: normalizeText(group.postedDate || ''),
      postedText: normalizeText(group.postedText || ''),
      jobUrls,
      duplicateCount,
      reasoning: normalizeText(group.reasoning || ''),
      source: 'LinkedIn Jobs Guest Search',
      searchTerm: $('Workflow Configuration').first().json.keywords,
      remoteFilter: true,
      detectedAt: $('Prepare Jobs For AI Deduplication').first().json.detectedAt,
      agentIndex: index
    }
  };
});

const now = Date.now();
const retentionMs = 30 * 24 * 60 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const seenOpportunities = staticData.seenOpportunities || {};

for (const [key, timestamp] of Object.entries(seenOpportunities)) {
  if (!timestamp || Number(timestamp) < now - retentionMs) {
    delete seenOpportunities[key];
  }
}

const freshItems = [];
for (const item of $input.all()) {
  const key = item.json.canonicalKey;
  if (!key) continue;
  if (seenOpportunities[key]) continue;

  seenOpportunities[key] = now;
  freshItems.push({
    json: {
      ...item.json,
      isNewSinceLastRun: true,
      alertDetectedAt: new Date(now).toISOString()
    }
  });
}

staticData.seenOpportunities = seenOpportunities;
return freshItems;

const decodeHtml = (value = '') => String(value)
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&#x27;/gi, "'")
  .replace(/&#x2F;/gi, '/')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .trim();

const sourceItems = $('Keep Only Newly Seen Opportunities').all();

const extractAboutHtml = (html = '') => {
  if (!html) return '';

  const patterns = [
    /<div class="show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<section[^>]*class="show-more-less-html[^"]*"[\s\S]*?<div class="show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>[\s\S]*?<\/section>/i,
    /<div class="description__text[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match?.[1]) return match[1].trim();
  }

  return '';
};

const stripTags = (value = '') => decodeHtml(
  String(value)
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li[^>]*>/gi, '- ')
    .replace(/<[^>]+>/g, ' ')
)
  .replace(/\r/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

return $input.all().map((item, index) => {
  const source = sourceItems[index]?.json || {};
  const jobDetailHtml = String(item.json.jobDetailHtml || '');
  const aboutTheJobHtml = extractAboutHtml(jobDetailHtml);
  const aboutTheJobText = stripTags(aboutTheJobHtml);

  return {
    json: {
      ...source,
      jobDetailHtml,
      aboutTheJobHtml,
      aboutTheJobText,
      aboutTheJobFound: Boolean(aboutTheJobText),
    },
  };
});

