const sourceItems = $('Extract About the Job').all();
const minFitScoreRaw = Number($('Workflow Configuration').first().json.minFitScore ?? 7);
const minFitScore = Number.isFinite(minFitScoreRaw)
  ? Math.min(10, Math.max(1, Math.round(minFitScoreRaw)))
  : 7;

const parseMaybeJson = (value) => {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;

  try {
    return JSON.parse(trimmed);
  } catch {
    return value;
  }
};

const findScoreObject = (value, depth = 0, seen = new Set()) => {
  if (depth > 8 || value == null) return null;

  const parsed = parseMaybeJson(value);

  if (Array.isArray(parsed)) {
    for (const entry of parsed) {
      const nested = findScoreObject(entry, depth + 1, seen);
      if (nested) return nested;
    }
    return null;
  }

  if (!parsed || typeof parsed !== 'object') return null;
  if (seen.has(parsed)) return null;

  if (parsed.fitScore != null) return parsed;

  seen.add(parsed);

  for (const key of ['output', 'response', 'data', 'result', 'content']) {
    const nested = findScoreObject(parsed[key], depth + 1, seen);
    if (nested) return nested;
  }

  for (const value of Object.values(parsed)) {
    const nested = findScoreObject(value, depth + 1, seen);
    if (nested) return nested;
  }

  return null;
};

const normalizeText = (value = '') => String(value).trim();
const allowedBands = new Set(['excellent', 'good', 'mixed', 'engineering-heavy', 'not-fit']);
const makeBand = (score) => {
  if (score >= 9) return 'excellent';
  if (score >= 7) return 'good';
  if (score >= 5) return 'mixed';
  if (score >= 3) return 'engineering-heavy';
  return 'not-fit';
};
const fullBlock = String.fromCharCode(9608);
const lightBlock = String.fromCharCode(9617);
const makeBar = (score) => `${fullBlock.repeat(score)}${lightBlock.repeat(10 - score)}`;

return $input.all().map((item, index) => {
  const source = sourceItems[index]?.json || {};
  const scoreObject = findScoreObject(item.json);

  if (!scoreObject) {
    throw new Error(`AI Score Job Fit returned no usable fit score for item ${index + 1}.`);
  }

  const fitScoreValue = Math.round(Number(scoreObject.fitScore));
  if (!Number.isFinite(fitScoreValue)) {
    throw new Error(`AI Score Job Fit returned an invalid fitScore for item ${index + 1}.`);
  }

  const fitScore = Math.min(10, Math.max(1, fitScoreValue));
  const fitBandRaw = normalizeText(scoreObject.fitBand).toLowerCase();
  const fitBand = allowedBands.has(fitBandRaw) ? fitBandRaw : makeBand(fitScore);
  const fitSummary = normalizeText(scoreObject.fitSummary || (fitScore >= minFitScore
    ? 'Strong automation fit for your profile.'
    : 'Role looks too engineering-heavy for your profile.'));
  const scoringReason = normalizeText(scoreObject.scoringReason || 'No scoring reason returned.');

  return {
    json: {
      ...source,
      fitScore,
      fitBand,
      fitSummary,
      scoringReason,
      fitScoreBar: makeBar(fitScore),
      minFitScore,
      passesFitScore: fitScore >= minFitScore,
    },
  };
}).filter((item) => item.json.passesFitScore);

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const escapeUrl = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/"/g, '&quot;');

const ICONS = {
  alert: String.fromCodePoint(0x1F680),
  role: String.fromCodePoint(0x1F4BC),
  company: String.fromCodePoint(0x1F3E2),
  fit: String.fromCodePoint(0x2B50),
  note: String.fromCodePoint(0x1F4AC),
  regions: String.fromCodePoint(0x1F30D),
  links: String.fromCodePoint(0x1F517),
  posted: String.fromCodePoint(0x23F0),
  date: String.fromCodePoint(0x1F4C5),
  dedupe: String.fromCodePoint(0x1F9E0),
  search: String.fromCodePoint(0x1F50D),
  filter: String.fromCodePoint(0x1F3AF),
  window: String.fromCodePoint(0x1F552),
};

const countryHints = {
  argentina: 'AR',
  australia: 'AU',
  austria: 'AT',
  belgium: 'BE',
  brazil: 'BR',
  bulgaria: 'BG',
  canada: 'CA',
