  uk: 'GB',
  'great britain': 'GB',
  england: 'GB',
  'united states': 'US',
  usa: 'US',
  vietnam: 'VN',
};

const usStateCodes = new Set([
  'al', 'ak', 'az', 'ar', 'ca', 'co', 'ct', 'dc', 'de', 'fl', 'ga', 'hi', 'ia', 'id', 'il', 'in',
  'ks', 'ky', 'la', 'ma', 'md', 'me', 'mi', 'mn', 'mo', 'ms', 'mt', 'nc', 'nd', 'ne', 'nh', 'nj',
  'nm', 'nv', 'ny', 'oh', 'ok', 'or', 'pa', 'ri', 'sc', 'sd', 'tn', 'tx', 'ut', 'va', 'vt', 'wa',
  'wi', 'wv', 'wy',
]);

const toFlagEmoji = (countryCode = '') => {
  const normalized = String(countryCode).trim().toUpperCase();
  if (!/^[A-Z]{2}$/.test(normalized)) return '';
  return Array.from(normalized)
    .map((char) => String.fromCodePoint(127397 + char.charCodeAt(0)))
    .join('');
};

const detectCountryCode = (value = '') => {
  const normalized = String(value).trim().toLowerCase();
  if (!normalized) return '';

  for (const [hint, code] of Object.entries(countryHints)) {
    if (normalized.includes(hint)) return code;
  }

  const parts = normalized.split(',').map((part) => part.trim()).filter(Boolean);
  const lastPart = parts[parts.length - 1] || '';

  if (countryHints[lastPart]) return countryHints[lastPart];
  if (usStateCodes.has(lastPart)) return 'US';

  return '';
};

const formatRegion = (value = '') => {
  const safeRegion = escapeHtml(value);
  const flag = toFlagEmoji(detectCountryCode(value));
  return flag ? `${safeRegion} ${flag}` : safeRegion;
};

const defaultBar = String.fromCharCode(9617).repeat(10);

return $input.all().map((item) => {
  const job = item.json;
  const regions = (job.regions || [])
    .map((region) => String(region).trim())
    .filter(Boolean);
  const regionLines = (regions.length ? regions : [job.primaryLocation || 'Worldwide'])
    .map((region) => formatRegion(region));
  const links = (job.jobUrls || [])
    .slice(0, 8)
    .map((url, index) => `<a href="${escapeUrl(url)}">Open posting ${index + 1}</a>`);

  const scoreValue = Number.isFinite(Number(job.fitScore)) ? String(Math.round(Number(job.fitScore))) : '?';
  const scoreBar = String(job.fitScoreBar || defaultBar);
  const minFitScore = Number.isFinite(Number(job.minFitScore)) ? Math.round(Number(job.minFitScore)) : 7;

  const messageLines = [
    `${ICONS.alert} <b>New LinkedIn Job Opportunity</b>`,
    '',
    `${ICONS.role} <b>Role:</b> ${escapeHtml(job.title || 'Unknown role')}`,
    `${ICONS.company} <b>Company:</b> ${escapeHtml(job.company || 'Unknown company')}`,
    `${ICONS.fit} <b>Fit Score:</b> ${escapeHtml(scoreBar)} ${escapeHtml(`${scoreValue}/10`)}`,
  ];

  if (job.fitSummary) {
    messageLines.push(`${ICONS.note} <b>Fit note:</b> ${escapeHtml(job.fitSummary)}`);
  }

  messageLines.push(
    '',
    `${ICONS.regions} <b>Regions:</b>`,
    '',
    ...regionLines,
    '',
    `${ICONS.links} <b>Merged postings:</b> ${escapeHtml(String(job.duplicateCount ?? 1))}`,
  );

  if (job.postedText) {
    messageLines.push(`${ICONS.posted} <b>Posted:</b> ${escapeHtml(job.postedText)}`);
  }

  if (job.postedDate) {
    messageLines.push(`${ICONS.date} <b>Posting date:</b> ${escapeHtml(job.postedDate)}`);
  }

  if (job.reasoning) {
    messageLines.push('', `${ICONS.dedupe} <b>AI dedupe note:</b>`, escapeHtml(job.reasoning));
  }

  messageLines.push(
    '',
    `${ICONS.links} <b>Links:</b>`,
    '',
    ...(links.length ? links : ['No links captured']),
    '',
    `${ICONS.search} <b>Search term:</b> ${escapeHtml(job.searchTerm || 'configured keywords')}`,
    `${ICONS.filter} <b>Filter:</b> Remote + Fit >= ${escapeHtml(String(minFitScore))}`,
    `${ICONS.window} <b>Window:</b> Last 24h`,
  );

  return {
    json: {
      ...job,
      telegramMessage: messageLines.join('\n')
    }
  };
});

const config = $('Workflow Configuration').first().json;
const enabled = config.easyApplyEnabled === true || String(config.easyApplyEnabled).toLowerCase() === 'true';
const webhookUrl = String(config.easyApplyWebhookUrl || '').trim();
const mode = String(config.easyApplyMode || 'fill_and_confirm').trim();

if (!enabled || !webhookUrl || webhookUrl.includes('YOUR-TUNNEL-URL')) {
  return [];
}

return $input.all().map((item) => {
  const job = item.json;
  const jobUrls = Array.isArray(job.jobUrls) ? job.jobUrls.filter(Boolean) : [];
  const jobUrl = jobUrls[0] || job.jobUrl || '';
  const taskId = `${job.canonicalKey || `${job.company || 'unknown'}|${job.title || 'unknown'}`}-${Date.now()}`
    .toLowerCase()
    .replace(/[^a-z0-9|._-]+/g, '-');

  return {
    json: {
      easyApplyWebhookUrl: webhookUrl,
      easyApplyMode: mode,
      easyApplyTask: {
        taskId,
        canonicalKey: job.canonicalKey || '',
        title: job.title || '',
        company: job.company || '',
        jobUrl,
        jobUrls,
        regions: job.regions || [],
        primaryLocation: job.primaryLocation || '',
        fitScore: job.fitScore,
        fitBand: job.fitBand || '',
        fitSummary: job.fitSummary || '',
        scoringReason: job.scoringReason || '',
        aboutTheJobText: job.aboutTheJobText || '',
        cvPath: config.cvPath || '',
        statusCallbackSecret: config.easyApplyStatusCallbackSecret || '',
        mode,
        sourceWorkflow: $workflow.name,
        createdAt: new Date().toISOString(),
      },
    },
  };
});

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const statusLabels = {
  queued: 'Queued in local browser agent',
  no_easy_apply: 'No Easy Apply button found',
  login_required: 'LinkedIn login required',
  unknown_questions: 'Needs your answer',
  extra_action_required: 'Extra application action required',
  ready_for_review: 'Ready for your review',
  error: 'Easy Apply agent error',
};

return $input.all().map((item) => {
  const expectedSecret = String(item.json.easyApplyStatusCallbackSecret || '');
  const telegramChatId = String(item.json.telegramChatId || '');
  const headers = item.json.headers || {};
  const body = item.json.body || item.json;
  const providedSecret = headers['x-easy-apply-status-secret']
    || headers['X-Easy-Apply-Status-Secret']
    || body.statusCallbackSecret
    || '';

  if (!expectedSecret.includes('PLACEHOLDER') && providedSecret !== expectedSecret) {
    throw new Error('Invalid Easy Apply status callback secret.');
  }

  const status = String(body.status || 'unknown');
  const questions = Array.isArray(body.questions) ? body.questions.filter(Boolean) : [];
  const label = statusLabels[status] || status;
  const lines = [
    'Easy Apply Status',
    '',
    `<b>Status:</b> ${escapeHtml(label)}`,
    `<b>Role:</b> ${escapeHtml(body.title || 'Unknown role')}`,
    `<b>Company:</b> ${escapeHtml(body.company || 'Unknown company')}`,
  ];

  if (body.message) {
    lines.push('', `<b>Message:</b> ${escapeHtml(body.message)}`);
  }

  if (questions.length) {
    lines.push('', '<b>Questions / actions needed:</b>');
    for (const question of questions.slice(0, 10)) {
      lines.push(`- ${escapeHtml(question)}`);
    }
  }

  if (body.jobUrl) {
    const safeUrl = String(body.jobUrl).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    lines.push('', `<a href="${safeUrl}">Open LinkedIn posting</a>`);
  }

  return {
    json: {
      ...body,
      telegramChatId,
      telegramMessage: lines.join('\n'),
    },
  };
});
